$layoutPath='C:\Users\Volo\Desktop\LEA_PLC\frontend\app\layout.tsx';$globalsPath='C:\Users\Volo\Desktop\LEA_PLC\frontend\app\globals.css';$layout=Get-Content -Raw -LiteralPath $layoutPath;if($layout -notmatch 'next/font/google'){$layout=$layout -replace 'import type \{ Metadata, Viewport \} from "next";','import type { Metadata, Viewport } from "next";`r`nimport { Outfit } from "next/font/google";'};if($layout -notmatch 'const outfit = Outfit'){$layout=$layout -replace 'export const metadata: Metadata = \{','const outfit = Outfit({ subsets: ["latin"], variable: "--font-outfit", display: "swap" });`r`n`r`nexport const metadata: Metadata = {'};$layout=[regex]::Replace($layout,'<body className="[^"]*">','<body className={`${outfit.variable} min-h-screen bg-background font-sans text-foreground antialiased`}>',1);Set-Content -LiteralPath $layoutPath -Value $layout -Encoding utf8;$globals=Get-Content -Raw -LiteralPath $globalsPath;if($globals -notmatch 'var\(--font-outfit\)'){$globals=$globals -replace '--font-sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto,','--font-sans: var(--font-outfit), ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto,'};if($globals -notmatch 'scroll-behavior: smooth'){$globals += "`r`nhtml {`r`n scroll-behavior: smooth;`r`n}`r`n"};Set-Content -LiteralPath $globalsPath -Value $globals -Encoding utf8;Write-Output 'Outfit patch applied'